export const ALL_REVIEWS: Review[] = Object.values(REVIEWS);

export const reviewByline = (review: Review) =>
  review.location ? `${review.author}, ${review.location}` : review.author;

// Shape used by the rotating carousels in the hero sections.
export const carouselReviews = (keys: string[]) =>
  keys.map((key, index) => ({
    id: index + 1,
    text: REVIEWS[key].excerpt ?? REVIEWS[key].text,
    author: reviewByline(REVIEWS[key]),
    stars: 5,
  }));
